"""task-5832262a: frame object with ring of inner color.
Ring thickness k = outer_h // (outer_h - inner_h); region = inner bbox expanded by (gap + k),
filled with inner color, original object redrawn on top."""
import numpy as np

def bbox_nonzero(g):
    xs=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v]
    return (min(i for i,_ in xs),min(j for _,j in xs),max(i for i,_ in xs),max(j for _,j in xs))

def bbox_color(g,c):
    xs=[(i,j) for i,r in enumerate(g) for j,v in enumerate(r) if v==c]
    return (min(i for i,_ in xs),min(j for _,j in xs),max(i for i,_ in xs),max(j for _,j in xs))

def transform(g):
    a=np.array(g)
    r0,c0,r1,c1=bbox_nonzero(g)
    ic=a[(r0+r1)//2,(c0+c1)//2]
    i0,j0,i1,j1=bbox_color(g,ic)
    oh=r1-r0+1; ih=i1-i0+1
    k=-(-ih//gap)  # ceil(ih/gap)
    e=(i0-r0)+k
    out=np.zeros_like(a)
    out[max(0,i0-e):min(a.shape[0]-1,i1+e)+1, max(0,j0-e):min(a.shape[1]-1,j1+e)+1]=ic
    out[r0:r1+1,c0:c1+1]=a[r0:r1+1,c0:c1+1]
    return out.tolist()
